import json
from pathlib import Path


def load_payload(path):
    """Read a UTF-8 JSON payload. Top-level object or array is legal."""
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ValueError("cannot read payload: %s" % path) from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("invalid JSON payload: %s" % path) from exc
    if data is None or isinstance(data, (bool, int, float, str)):
        raise ValueError("top-level payload must be an object or array")
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level payload must be an object or array")
    return data

