import heapq
import math
from collections import defaultdict, deque


def _fail(msg):
    raise ValueError(msg)


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _nonempty_str(v, field):
    if not isinstance(v, str) or v.strip() == "":
        _fail("%s must be a non-empty string" % field)
    return v


def _check_finite(value, where="payload"):
    if isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            _fail("non-finite number in %s" % where)
    elif isinstance(value, dict):
        for k, v in value.items():
            _check_finite(v, where + "." + str(k))
    elif isinstance(value, list):
        for i, v in enumerate(value):
            _check_finite(v, where + "[%d]" % i)


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        _fail("payload count does not match contract inputs")
    payload = payloads[0]
    _check_finite(payload)
    if not isinstance(payload, dict):
        _fail("trust_paths input must be an object")

    if "now" not in payload or not _is_int(payload["now"]) or payload["now"] < 0:
        _fail("now must be a non-negative int")
    now = payload["now"]

    nodes = {}
    raw_nodes = payload.get("nodes")
    if not isinstance(raw_nodes, list):
        _fail("nodes must be a list")
    for item in raw_nodes:
        if not isinstance(item, dict):
            _fail("each node must be an object")
        nid = _nonempty_str(item.get("id"), "node id")
        if nid in nodes:
            _fail("duplicate node id: %s" % nid)
        expires = item.get("expires")
        if not _is_int(expires) or expires < 0:
            _fail("node expires must be a non-negative int")
        revoked = item.get("revoked")
        if not isinstance(revoked, bool):
            _fail("node revoked must be a bool")
        nodes[nid] = {"expires": expires, "revoked": revoked}

    raw_roots = payload.get("roots")
    if not isinstance(raw_roots, list):
        _fail("roots must be a list")
    roots_set = set()
    for r in raw_roots:
        r = _nonempty_str(r, "root id")
        if r not in nodes:
            _fail("unknown root id: %s" % r)
        roots_set.add(r)

    raw_edges = payload.get("edges")
    if not isinstance(raw_edges, list):
        _fail("edges must be a list")
    edges = []
    seen_edges = set()
    for item in raw_edges:
        if not isinstance(item, dict):
            _fail("each edge must be an object")
        issuer = _nonempty_str(item.get("issuer"), "edge issuer")
        subject = _nonempty_str(item.get("subject"), "edge subject")
        expires = item.get("expires")
        if not _is_int(expires) or expires < 0:
            _fail("edge expires must be a non-negative int")
        if issuer not in nodes or subject not in nodes:
            _fail("edge endpoint does not exist")
        key = (issuer, subject)
        if key in seen_edges:
            _fail("duplicate edge: %s -> %s" % key)
        seen_edges.add(key)
        edges.append((issuer, subject, expires))

    alive = {nid: n for nid, n in nodes.items() if not n["revoked"] and n["expires"] > now}
    alive_edges = []
    for issuer, subject, expires in edges:
        if issuer in alive and subject in alive and expires > now:
            alive_edges.append((issuer, subject, expires))

    adj = defaultdict(list)
    for issuer, subject, expires in alive_edges:
        adj[issuer].append((subject, expires))

    best = {}
    queue = []
    for r in roots_set:
        if r in alive:
            b = alive[r]["expires"]
            best[r] = b
            heapq.heappush(queue, (-b, r))
    while queue:
        negb, u = heapq.heappop(queue)
        if -negb != best[u]:
            continue
        bu = best[u]
        for v, ew in adj[u]:
            cand = min(bu, ew, alive[v]["expires"])
            if cand > best.get(v, -1):
                best[v] = cand
                heapq.heappush(queue, (-cand, v))

    trusted = []
    for nid in sorted(best):
        path = _best_path(nid, best[nid], alive, alive_edges, roots_set)
        trusted.append({"id": nid, "path": path, "valid_until": best[nid]})

    untrusted = sorted(n for n in nodes if n not in best)
    return {"name": contract["name"], "result": {"trusted": trusted, "untrusted": untrusted}}


def _best_path(target, bottleneck, alive, alive_edges, roots_set):
    sub_adj = defaultdict(list)
    sub_radj = defaultdict(list)
    for issuer, subject, expires in alive_edges:
        if alive[issuer]["expires"] >= bottleneck and alive[subject]["expires"] >= bottleneck and expires >= bottleneck:
            sub_adj[issuer].append(subject)
            sub_radj[subject].append(issuer)

    sources = [r for r in roots_set if r in alive and alive[r]["expires"] >= bottleneck]
    dist = {}
    queue = deque()
    for s in sources:
        dist[s] = 0
        queue.append(s)
    while queue:
        u = queue.popleft()
        for v in sub_adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                queue.append(v)
    if target not in dist:
        return [target]

    levels = defaultdict(list)
    for nid, d in dist.items():
        if d <= dist[target]:
            levels[d].append(nid)

    best_path = {s: (s,) for s in sources}
    for depth in range(1, dist[target] + 1):
        for v in levels[depth]:
            candidates = []
            for u in sub_radj[v]:
                if u in best_path:
                    candidates.append(best_path[u] + (v,))
            best_path[v] = min(candidates)
    return list(best_path[target])

