import fnmatch


def _fail(msg):
    raise ValueError(msg)


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _nonempty_str(v, field):
    if not isinstance(v, str) or v.strip() == "":
        _fail("%s must be a non-empty string" % field)
    return v


def _specificity(resource, action):
    count = 0
    for ch in resource + action:
        if ch not in "*?[]":
            count += 1
    return count


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        _fail("payload count does not match contract inputs")
    payload = payloads[0]
    if not isinstance(payload, dict):
        _fail("policy_precedence input must be an object")

    rules = []
    seen_ids = set()
    raw_rules = payload.get("rules")
    if not isinstance(raw_rules, list):
        _fail("rules must be a list")
    for item in raw_rules:
        if not isinstance(item, dict):
            _fail("each rule must be an object")
        rid = item.get("id")
        if not isinstance(rid, str) or rid.strip() == "":
            _fail("rule id must be a non-empty string")
        key = rid.strip()
        if key in seen_ids:
            _fail("duplicate rule id: %s" % rid)
        seen_ids.add(key)
        resource = _nonempty_str(item.get("resource"), "rule resource")
        action = _nonempty_str(item.get("action"), "rule action")
        priority = item.get("priority")
        if not _is_int(priority):
            _fail("rule priority must be an int")
        effect = item.get("effect")
        if effect not in ("allow", "deny"):
            _fail("rule effect must be allow or deny")
        rules.append({
            "id": rid,
            "resource": resource,
            "action": action,
            "priority": priority,
            "effect": effect,
            "specificity": _specificity(resource, action),
        })

    requests = []
    raw_requests = payload.get("requests")
    if not isinstance(raw_requests, list):
        _fail("requests must be a list")
    for item in raw_requests:
        if not isinstance(item, dict):
            _fail("each request must be an object")
        resource = _nonempty_str(item.get("resource"), "request resource").strip()
        action = _nonempty_str(item.get("action"), "request action").strip()
        requests.append((resource, action))

    decisions = []
    allow = 0
    deny = 0
    for resource, action in requests:
        winner = None
        for rule in rules:
            if fnmatch.fnmatchcase(resource, rule["resource"]) and fnmatch.fnmatchcase(action, rule["action"]):
                if winner is None or _better(rule, winner):
                    winner = rule
        if winner is None:
            effect = "deny"
            rule_id = None
        else:
            effect = winner["effect"]
            rule_id = winner["id"]
        if effect == "allow":
            allow += 1
        else:
            deny += 1
        decisions.append({"resource": resource, "action": action, "effect": effect, "rule_id": rule_id})

    return {"name": contract["name"], "result": {"decisions": decisions, "allow": allow, "deny": deny}}


def _better(candidate, current):
    # Order: priority desc, specificity desc, deny first, id asc.
    if candidate["priority"] != current["priority"]:
        return candidate["priority"] > current["priority"]
    if candidate["specificity"] != current["specificity"]:
        return candidate["specificity"] > current["specificity"]
    rank = {"deny": 0, "allow": 1}
    if rank[candidate["effect"]] != rank[current["effect"]]:
        return rank[candidate["effect"]] < rank[current["effect"]]
    return candidate["id"] < current["id"]

