            _check_finite(v, where + "." + str(k))
    elif isinstance(value, list):
        for i, v in enumerate(value):
            _check_finite(v, where + "[%d]" % i)


def _unwrap(payload):
    if not isinstance(payload, dict) or set(payload.keys()) != {"name", "result"}:
        _fail("upstream input must be a component wrapper")
    result = payload["result"]
    if not isinstance(result, dict):
        _fail("upstream result must be an object")
    return result


def transform(payloads, contract):
    if not isinstance(payloads, list) or len(payloads) != len(contract.get("inputs", [])):
        _fail("payload count does not match contract inputs")

    for p in payloads:
        _check_finite(p)

    coverage = payloads[0]
    if not isinstance(coverage, dict):
        _fail("notice_coverage input must be an object")

    # Validate the complete local coverage schema first.
    clients = {}
    raw_clients = coverage.get("clients")
    if not isinstance(raw_clients, list):
        _fail("clients must be a list")
    for item in raw_clients:
        if not isinstance(item, dict):
            _fail("each client must be an object")
        cid = _nonempty_str(item.get("id"), "client id")
        if cid in clients:
            _fail("duplicate client id: %s" % cid)
        weight = item.get("weight")
        if not _is_int(weight) or weight < 0:
            _fail("client weight must be a non-negative int")
        deadline = item.get("deadline")
        if not _is_int(deadline) or deadline < 0:
