def _optimize(clients, windows, budget, cooldown):
    mandatory = [cid for cid, c in clients.items() if c["mandatory"]]
    n = len(windows)

    best_ids = None
    best_value = None
    best_cost = None
    best_completion = None

    for mask in range(1 << n):
        selected = [windows[i] for i in range(n) if (mask >> i) & 1]
        ordered = sorted(selected, key=lambda w: (w["start"], w["end"], w["id"]))

        prev = None
        overlap = False
        for w in ordered:
            if prev is not None and prev["end"] + cooldown > w["start"]:
                overlap = True
                break
            prev = w
        if overlap:
            continue

        cost = sum(w["cost"] for w in selected)
        if cost > budget:
            continue

        covered = set()
        for w in selected:
            for cid in w["clients"]:
                if w["end"] <= clients[cid]["deadline"]:
                    covered.add(cid)

        if not all(cid in covered for cid in mandatory):
            continue

        value = sum(clients[cid]["weight"] for cid in covered)
        ids = tuple(sorted(w["id"] for w in selected))

        better = best_ids is None
        if not better:
            if value != best_value:
                better = value > best_value
            elif cost != best_cost:
                better = cost < best_cost
            else:
                better = ids < best_ids
        if better:
            best_ids = ids
            best_value = value
            best_cost = cost
            best_completion = {}
            for cid in covered:
                ends = [
                    w["end"]
                    for w in selected
                    if cid in w["clients"] and w["end"] <= clients[cid]["deadline"]
                ]
                best_completion[cid] = min(ends)

    if best_ids is None:
        return {"feasible": False, "selected": [], "completion": {}, "value": 0, "cost": 0}
    return {
        "feasible": True,
        "selected": list(best_ids),
        "value": best_value,
        "cost": best_cost,
        "completion": best_completion,
    }

