import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _contracts():
    found = []
    for p in ROOT.rglob("contract.json"):
        rel = p.relative_to(ROOT)
        if "outputs" in rel.parts:
            continue
        found.append(p)
    return sorted(found)


def _dependency_order():
    contracts = {}
    for p in _contracts():
        c = json.loads(p.read_text(encoding="utf-8"))
        contracts[c["name"]] = {"path": p, "contract": c}

    output_owner = {}
    for name, entry in contracts.items():
        output_owner[entry["contract"]["output"]] = name

    deps = {}
    for name, entry in contracts.items():
        names = set()
        for inp in entry["contract"]["inputs"]:
            if inp in output_owner:
                names.add(output_owner[inp])
        deps[name] = names

    order = []
    state = {}

    def visit(name):
        mark = state.get(name)
        if mark == 2:
            return
        if mark == 1:
            raise ValueError("cyclic component dependency")
        state[name] = 1
        for dep in sorted(deps[name]):
            visit(dep)
        state[name] = 2
        order.append(name)

    for name in sorted(contracts):
        visit(name)
    return [(name, contracts[name]) for name in order]


def main():
    ordered = _dependency_order()
    for name, entry in ordered:
        render = entry["path"].with_name("render.py")
        subprocess.run([sys.executable, str(render)], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run([sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True)


if __name__ == "__main__":
    main()

