import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _write_json(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(data, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


def _attention(core_object):
    names = []
    components = core_object.get("components", {})
    for name, result in components.items():
        include = False
        if "blocked" in result and result["blocked"] is True:
            include = True
        if not include and "feasible" in result and result["feasible"] is False:
            include = True
        if not include and "compatible" in result and result["compatible"] is False:
            include = True
        if not include and "deny" in result and isinstance(result["deny"], int) and result["deny"] > 0:
            include = True
        if not include and "score_total" in result and isinstance(result["score_total"], (int, float)) and result["score_total"] >= 20:
            include = True
        if include:
            names.append(name)
    return sorted(set(names))


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core_object = json.loads(core_path.read_text(encoding="utf-8"))
    components = core_object["components"]
    compact = json.dumps(
        core_object,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    digest = hashlib.sha256(compact).hexdigest()
    report = {
        "title": "证书轮换准备",
        "component_count": len(components),
        "sha256": digest,
        "attention": _attention(core_object),
    }
    _write_json(ROOT / "outputs" / "final_report.json", report)


if __name__ == "__main__":
    main()

